public class BracketCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("empty string is balanced", true, BracketChecker.isBalanced(""));
            check("nested mix ([{}])", true, BracketChecker.isBalanced("([{}])"));
            check("sequence ()[]{} ", true, BracketChecker.isBalanced("()[]{}"));
            check("wrong pair (]", false, BracketChecker.isBalanced("(]"));
            check("unclosed (((", false, BracketChecker.isBalanced("((("));
            check("closer first )(", false, BracketChecker.isBalanced(")("));
            check("crossed [(])", false, BracketChecker.isBalanced("[(])"));
            check("letters ignored (a[b]c)", true, BracketChecker.isBalanced("(a[b]c)"));
            check("extra closer ()]", false, BracketChecker.isBalanced("()]"));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

