import java.util.ArrayDeque;

public class BracketChecker {

    public static boolean isBalanced(String s) {
        ArrayDeque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            } else if (c == ')' || c == ']' || c == '}') {
                if (stack.isEmpty()) {
                    return false;
                }
                char open = stack.pop();
                if (c == ')' && open != '(') {
                    return false;
                }
                if (c == ']' && open != '[') {
                    return false;
                }
                if (c == '}' && open != '{') {
                    return false;
                }
            }
        }
        return stack.isEmpty();
    }
}
